56	    fn visit_module_item_list(&mut self, list: JsModuleItemList) {
57	        for item in list {
58	            match item {
59	                AnyJsModuleItem::AnyJsStatement(statement) => match statement {
60	                    AnyJsStatement::JsVariableStatement(variable_statement) => {
61	                        self.visit_js_variable_statement(variable_statement.clone());
62	                    }
63	                    AnyJsStatement::JsExpressionStatement(expr_statement) => {
64	                        self.visit_js_expression_statement(expr_statement.clone());
65	                    }
66	                    AnyJsStatement::JsFunctionDeclaration(decl) => {
67	                        self.register_js_binding(decl.id());
68	                    }
69	                    AnyJsStatement::JsClassDeclaration(decl) => {
70	                        self.register_js_binding(decl.id());
71	                    }
72	                    AnyJsStatement::TsEnumDeclaration(decl) => {
73	                        self.register_js_binding(decl.id());
74	                    }
75	                    AnyJsStatement::TsInterfaceDeclaration(decl) => {
76	                        self.register_ts_identifier_binding(decl.id());
77	                    }
