37	    /// Visit a non-source snippet to track value references
38	    pub(crate) fn visit_non_source_snippet(&mut self, root: &AnyJsRoot) {
39	        let preorder = root.syntax().preorder();
40	
41	        for event in preorder {
42	            match event {
43	                WalkEvent::Enter(node) => {
44	                    if let Some(reference) = JsReferenceIdentifier::cast_ref(&node) {
45	                        self.visit_reference_identifier(reference);
46	                    } else if let Some(member) = JsStaticMemberExpression::cast_ref(&node) {
47	                        self.visit_static_member_expression(member);
48	                    }
49	                }
50	                WalkEvent::Leave(_) => {}
51	            }
52	        }
53	    }
54	
55	    /// Visit an HTML root to track component element names as value references.
56	    ///
57	    /// This extracts component names from Vue/Svelte templates like:
58	    /// - `<Component />` → tracks `Component`
59	    /// - `<AvatarPrimitive.Fallback>` → tracks `AvatarPrimitive`
60	    pub(crate) fn visit_html_root(&mut self, root: &HtmlRoot) {
61	        for node in root.syntax().descendants() {
62	            // Check HtmlElement: <Component>...</Component>
63	            if let Some(element) = HtmlElement::cast_ref(&node) {
64	                self.visit_html_element(&element);
65	            }
66	
67	            // Check HtmlSelfClosingElement: <Component />
68	            if let Some(element) = HtmlSelfClosingElement::cast_ref(&node) {
69	                self.visit_html_self_closing_element(&element);
70	            }
71	        }
72	    }
