30	impl AstroFileHandler {
31	    /// It extracts the JavaScript code contained in the frontmatter of an Astro file
32	    ///
33	    /// If the frontmatter doesn't exist, an empty string is returned.
34	    pub fn input(text: &str) -> &str {
35	        let mut matches = Self::matches(text);
36	        match (matches.next(), matches.next()) {
37	            (Some(start), Some(end)) => &text[start.end()..end.start()],
38	            _ => "",
39	        }
40	    }
41	
42	    /// Returns the start byte offset of the Astro fence
43	    pub fn start(input: &str) -> Option<u32> {
44	        ASTRO_FENCE.find_iter(input).next().map(|m| m.end() as u32)
45	    }
46	
47	    fn matches(input: &str) -> Matches<'_, '_> {
48	        ASTRO_FENCE.find_iter(input)
49	    }
50	
51	    /// It takes the original content of an Astro file, and new output of an Astro file. The output is only the content contained inside the
52	    /// Astro fences. The function replaces `output` inside those fences.
53	    pub fn output(input: &str, output: &str) -> String {
54	        let mut matches = Self::matches(input);
55	        if let (Some(start), Some(end)) = (matches.next(), matches.next()) {
56	            format!(
57	                "{}{}{}",
58	                &input[..start.end() + 1],
59	                output.trim_start(),
60	                &input[end.start()..]
61	            )
62	        } else {
63	            input.to_string()
64	        }
65	    }
66	}
