171	/// Returns the lexer context to use when parsing component names and member expressions.
172	/// This allows `.` to be lexed as a token for member expressions like Component.Member
173	/// We reuse [HtmlLexContext::InsideTagWithDirectives] context because it supports `.` lexing, but this is ONLY used
174	/// for parsing component names, not for parsing attributes.
175	#[inline(always)]
176	fn component_name_context(p: &HtmlParser) -> HtmlLexContext {
177	    if Vue.is_supported(p) || Svelte.is_supported(p) || Astro.is_supported(p) {
178	        // Use HtmlLexContext::InsideTagWithDirectives for all component-supporting files when parsing component names
179	        // This allows `.` to be lexed properly for member expressions
180	        // Note: This is safe because we only use this context for tag names, not attributes
181	        HtmlLexContext::InsideTagWithDirectives {
182	            svelte: Svelte.is_supported(p),
183	        }
184	    } else {
185	        HtmlLexContext::InsideTag
186	    }
187	}
