191	fn parse_any_tag_name(p: &mut HtmlParser) -> ParsedSyntax {
192	    if !is_at_start_literal(p) {
193	        return Absent;
194	    }
195	    let tag_text = p.cur_text();
196	
197	    // Check if this could be a component or has member expression
198	    let is_component = is_possible_component(p, tag_text);
199	    let has_member_expression = !p.options().is_html() && p.nth_at(1, T![.]);
200	
201	    // Step 1: Parse base name
202	    let name = if is_component || has_member_expression {
203	        // Parse as component name - use component_name_context to allow `.` for member expressions
204	        let m = p.start();
205	        p.bump_with_context(HTML_LITERAL, component_name_context(p));
206	        Present(m.complete(p, HTML_COMPONENT_NAME))
207	    } else {
208	        // Parse as regular HTML tag
209	        parse_literal(p, HTML_TAG_NAME)
210	    };
211	    // Step 2: Extend with member access if present (using .map() pattern from JSX parser)
212	    name.map(|mut name| {
